// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: actor address and amount to deposit
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a wide usable range but not absurdly huge to avoid overflow in test harness
        amount = bound(amount, 0, 1 ether);
        // ensure actor is non-zero address to be a valid caller
        vm.assume(actor != address(0));

        // fund the actor so they can send the amount
        vm.deal(actor, amount);

        // read balance before
        uint256 before = c.balances(actor);

        // perform Deposit as actor with given amount
        vm.prank(actor);
        // deposit via payable call; if amount == 0 this should be a no-op but still allowed
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        // ensure the call succeeded on the reference; we assert property only via c's getter below
        // read balance after
        uint256 after = c.balances(actor);

        // General rule (single assertion): after == before + amount
        // This holds for the reference for all inputs; the mutant that subtracts will fail for some inputs
        assertTrue(after == before + amount);
    }
}

