pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor address and amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep amount within reasonable bounds (but wide) to avoid overflow in vm.deal
        amount = bound(amount, 0, 1 ether);

        // Ensure actor has funds to send
        vm.deal(actor, amount);

        // Record balance before via public getter
        uint256 before = c.balances(actor);

        // Perform Deposit() as actor with value `amount`
        vm.prank(actor);
        // call Deposit payable; if it reverts, treat as failure of call
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // For the correct contract, a successful Deposit call never decreases balances[actor].
        // We assert that either the call reverted (ok == false) or, if it succeeded, the balance after is >= before.
        // This single assertTrue observes c through its public getter.
        uint256 after = c.balances(actor);
        assertTrue(!ok || after >= before);
    }
}

