pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount within reasonable bounds relative to EVM balance space
        amount = bound(amount, 0, type(uint96).max);

        // initial total sum across multiple addresses: we can only read public balances by key.
        // choose two addresses to allow differing-key behavior; include actor and another.
        address other = address(uint160(uint256(keccak256(abi.encodePacked(actor, amount)))));

        // fund actors so Deposit can send value
        vm.deal(actor, amount);
        vm.deal(other, amount);

        // read initial totals
        uint256 before_actor = c.balances(actor);
        uint256 before_other = c.balances(other);
        uint256 before_total = before_actor + before_other;

        // perform deposit from actor of 'amount'
        vm.prank(actor);
        c.Deposit{value: amount}();

        // read after totals
        uint256 after_actor = c.balances(actor);
        uint256 after_other = c.balances(other);
        uint256 after_total = after_actor + after_other;

        // General rule: the total sum of all balances (as approximated here by two sampled keys) increases by exactly the deposited amount
        // The mutant that subtracts msg.value from balances can make this total decrease for some inputs.
        assertTrue(after_total == before_total + amount);
    }
}

