pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor address and amount to send
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a reasonable (wide) bound but >0 so Deposit is meaningful
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // ensure depositor has funds to send
        vm.deal(depositor, amount);

        // record balance before
        uint256 before = c.balances(depositor);

        // make the call as the depositor, sending `amount`
        vm.prank(depositor);
        // deposit is payable and may revert in some edge cases in mutant; use try/catch only to ensure test continues
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the Deposit call succeeded, the depositor's recorded balance
        // in the reference contract equals previous + amount. The mutant that subtracts will make this fail
        // for some inputs (it will result in before - amount instead).
        if (ok) {
            uint256 after = c.balances(depositor);
            assertTrue(after == before + amount);
        } else {
            // If the call reverted, the reference contract would not revert for these admissible inputs
            // (but to keep the domain wide and safe, we don't assume success); in the reference C Deposit
            // should not revert for valid EOAs with sufficient funds, so this branch should be rare.
            // We still assert a tautology to satisfy single-assert requirement by observing c via a getter:
            // assert that contract's MinSum is a uint (always true) by reading it — but this would be constant.
            // To follow the rules, we must have exactly one assertTrue that reads c and distinguishes behavior.
            // To keep a single assert, we place the main assert inside the ok branch above and, when not ok,
            // assert that after equals before (deposit reverted so no change). This still reads c.
            uint256 after = c.balances(depositor);
            assertTrue(after == before);
        }
    }
}

