contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep amt in a reasonable range (non-negative, not exceeding contract-addressable limits)
        vm.assume(depositor != address(0));
        amt = bound(amt, 0, 1 ether);

        // record total balances before
        uint256 sumBefore = 0;
        // we cannot iterate over mapping keys; but we can use address(this) and depositor and another address choice.
        // Instead observe contract's balance (Ether held) and the public balances(depositor) getter.
        // The intended universal property: after Deposit, total of all recorded balances (represented by sumBefore + change) increases by amt.
        // We use address(c).balance as the authoritative on-chain Ether held and balances(depositor) as recorded balance for depositor.

        uint256 balBefore_contract = address(c).balance;
        uint256 balBefore_depositor = c.balances(depositor);

        // prepare depositor with funds and perform deposit
        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.Deposit{value: amt}();

        uint256 balAfter_contract = address(c).balance;
        uint256 balAfter_depositor = c.balances(depositor);

        // The general invariant (single assert): the increase in the contract's held Ether equals the increase in the recorded depositor balance plus any difference for other keys.
        // For the correct contract, Deposit increases both address(c).balance and balances(depositor) by amt, so:
        // balAfter_contract - balBefore_contract == balAfter_depositor - balBefore_depositor == amt
        // We assert that the contract's Ether increase equals the recorded depositor balance increase.
        // The mutant that omits updating balances will make the depositor balance increase be zero while contract balance increases by amt,
        // violating equality for some inputs.

        assertTrue((balAfter_contract - balBefore_contract) == (balAfter_depositor - balBefore_depositor));
    }
}

