// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: actor (depositor), amount to deposit, minSum to set, collect amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 minSum, uint256 collectAmt) public {
        // admissible domain: non-zero deposit amount, depositor not zero address
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 1, 1 ether); // keep amount reasonable but fuzzed
        minSum = bound(minSum, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // deploy a Reverter helper that will be the target of the low-level call in Collect
        Reverter rev = new Reverter();

        // initialize c: set MinSum and Log to point to a benign LogFile (use C's LogFile type by deploying LogFile)
        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));
        c.SetMinSum(minSum);

        // fund depositor
        vm.deal(depositor, depositAmt + 1 ether);

        // depositor makes a deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        uint256 balAfter = c.balances(depositor);

        // If depositor balance is less than minSum, Collect should simply do nothing (no revert) per reference.
        // We only care about the case where balances >= MinSum and balances >= collectAmt, and when the recipient
        // call fails (we route msg.sender to the Reverter via prank). Under those conditions the reference will attempt
        // the low-level call which will revert (return false) and then revert the Collect; thus the call should revert
        // and balances should remain unchanged. The mutant's change to logged value can alter behavior for some inputs.

        // Only test the meaningful scenario: depositor's balance >= MinSum and >= collectAmt and collectAmt > 0
        vm.assume(balAfter >= minSum);
        vm.assume(balAfter >= collectAmt);
        vm.assume(collectAmt > 0);

        // Now attempt Collect but make msg.sender be the Reverter contract so the low-level call from C to msg.sender will revert
        // Use try/catch to capture whether Collect reverted.
        bool ok;
        vm.prank(address(rev));
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): for all admissible inputs, the reference contract will revert Collect when
        // the recipient call fails, so ok must be false. The buggy mutant can make this assertion fail for some inputs.
        assertTrue(!ok);
    }
}

// Minimal adversarial helper whose fallback will revert on plain calls
contract Reverter {
    fallback() external payable { revert("revert"); }
}

// Minimal LogFile to satisfy SetLogFile parameter type
contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

