pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: sender address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep amount in a wide but sensible range (nonzero and not overflowing trivial bounds)
        vm.assume(depositor != address(0));
        amt = bound(amt, 1, 1 ether);

        // Deploy malicious log that re-enters C during AddMessage and calls Deposit again
        ReentrantLog bad = new ReentrantLog(address(c));

        // set the contract's Log to the malicious log and initialize MinSum low
        // These setter calls must be done by any caller; use this test contract
        c.SetLogFile(address(bad));
        c.SetMinSum(1);
        c.Initialized();

        // fund depositor so they can send ETH
        vm.deal(depositor, amt * 2);

        // record old balance for depositor as seen by c
        uint256 old = c.balances(depositor);

        // Have depositor call Deposit; the ReentrantLog during AddMessage will re-enter and call Deposit again
        vm.prank(depositor);
        c.Deposit{value: amt}();

        // After the Deposit completes, the invariant for the reference is:
        // balances(depositor) == old + amt
        // The single assertion reads c's public getter. The reference preserves this for all inputs;
        // the mutant (which logs before updating) can be broken by the reentrant log to make balances differ.
        assertTrue(c.balances(depositor) == old + amt);
    }
}

// Minimal adversarial helper: during AddMessage it re-enters C.Deposit to cause effects visible if C logs before updating balances
contract ReentrantLog {
    address target;
    bool first = true;
    constructor(address _t) {
        target = _t;
    }

    // signature matches AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory) public {
        // On the first call, re-enter target.Deposit (causing a nested Deposit call from the same original sender)
        if (first) {
            first = false;
            // call Deposit with 0 value to simulate re-entrancy; use low-level call to forward no value
            // This will trigger Deposit() from this contract's context; to actually send ETH we need the original caller to have done that
            // The nested call is intended to exercise order-sensitivity between logging and balance updates
            (bool ok, ) = target.call(abi.encodeWithSignature("Deposit()"));
            require(ok);
        }
    }
}

